'use strict';
const AIS_ENDPOINT='https://oceancentinell-ais-gateway-production.up.railway.app/positions';
let aisState={enabled:false,configured:false,connected:false,error:null,positions:[],lastMessageAt:null,checkedAt:null},aisTimer=null,aisPending=false,selectedAIS=null;
function aisConnectionPanel(){const status=!aisState.enabled?'Not started':aisState.error==='provider_key_required'?'Provider key required':aisState.error?'Connection unavailable':aisState.connected?'Receiving AIS':aisState.configured?'Waiting for AIS':'Checking gateway';return `<div class="eyebrow">REGIONAL AIS OBSERVATIONS</div><h2>${status}</h2><div class="status-row"><span>Source</span><span>AISStream · Server gateway</span></div><div class="status-row"><span>Latest reception UTC</span><span>${e(aisState.lastMessageAt||'None received')}</span></div><div class="status-row"><span>Observed vessels</span><span>${aisState.positions.length}</span></div><div class="actions"><button data-ais-action="start">${aisState.enabled?'Refresh AIS':'Start AIS connection'}</button><button data-ais-action="stop" class="quiet">Pause AIS</button></div><p class="muted">Public regional traffic, separate from the fictional sample fleet. Reports can be delayed or missing. Gray symbols mark reports received over 3 minutes ago; observations expire after 30 minutes.</p>${aisState.error==='provider_key_required'?'<div class="notice">The gateway is running. An AISStream account and a server-side API key are still required. No real vessel positions have been received.</div>':''}${aisState.enabled&&aisState.positions.length?`<div class="ais-vessel-list">${aisState.positions.slice(0,20).map(p=>`<button class="quiet" data-ais="${e(p.mmsi)}">${e(p.name)} · ${e(p.mmsi)}</button>`).join('')}</div>`:''}<p class="source">Coverage: 24–34° N, 85–78° W. Reference map only; not for navigation.</p>`}
function refreshAISPanel(){const label=document.getElementById('sourceStatus');if(label)label.textContent=aisState.enabled&&aisState.connected?'Sample records + AIS observations':'Sample records · AIS pending';const panel=document.getElementById('ais-service');if(panel)panel.innerHTML=aisConnectionPanel()}
function validateAISResponse(v){return v&&v.provider==='AISStream'&&typeof v.configured==='boolean'&&typeof v.connected==='boolean'&&Array.isArray(v.positions)&&v.positions.length<=500&&v.positions.every(p=>p&&/^\d{9}$/.test(p.mmsi)&&typeof p.name==='string'&&p.name.length<=100&&Number.isFinite(p.lat)&&p.lat>=24&&p.lat<=34&&Number.isFinite(p.lon)&&p.lon>=-85&&p.lon<=-78&&Number.isFinite(Date.parse(p.receivedAt))&&[p.speedKnots,p.courseDegrees].every(x=>x===null||Number.isFinite(x)))}
function receiveAIS(v){aisPending=false;if(!validateAISResponse(v)){aisFailed();return}aisState={...aisState,configured:v.configured,connected:v.connected,error:v.error||null,lastMessageAt:v.lastMessageAt||null,checkedAt:Date.now(),positions:v.positions};refreshAISPanel();if(document.getElementById('operating-map'))drawMap();clearTimeout(aisTimer);if(aisState.enabled&&!document.hidden&&location.hash.includes('map')&&v.error!=='provider_key_required')aisTimer=setTimeout(fetchAIS,15000)}
function aisFailed(){aisPending=false;aisState.connected=false;aisState.error='network_unavailable';refreshAISPanel();if(document.getElementById('operating-map'))drawMap();clearTimeout(aisTimer);if(aisState.enabled&&!document.hidden&&location.hash.includes('map'))aisTimer=setTimeout(fetchAIS,30000)}
async function fetchAIS(){if(aisPending||!aisState.enabled||document.hidden)return;aisPending=true;refreshAISPanel();if(window.CentinellDevice?.fetchAIS){window.CentinellDevice.fetchAIS();return}try{const r=await fetch(AIS_ENDPOINT,{credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();receiveAIS(await r.json())}catch{aisFailed()}}
function startAIS(){aisState.enabled=true;clearTimeout(aisTimer);fetchAIS()}
function stopAIS(){aisState.enabled=false;aisState.connected=false;clearTimeout(aisTimer);refreshAISPanel();if(document.getElementById('operating-map'))drawMap()}
function aisMarkers(xy){if(!aisState.enabled)return '';return aisState.positions.filter(p=>Date.now()-Date.parse(p.receivedAt)<=1800000).map(p=>{const [x,y]=xy([p.lon,p.lat]),stale=Date.now()-Date.parse(p.receivedAt)>180000;return `<g class="ais-marker${stale?' stale':''}" role="button" tabindex="0" data-ais="${e(p.mmsi)}" aria-label="View AIS vessel ${e(p.name)}" transform="translate(${x},${y})"><path d="M0 -9L7 7 0 4 -7 7Z"/><title>${e(p.name)} · MMSI ${e(p.mmsi)}</title></g>`}).join('')}
function chooseAIS(id){const p=aisState.positions.find(p=>p.mmsi===id);if(!p)return;selectedAIS=id;const age=Math.max(0,Math.floor((Date.now()-Date.parse(p.receivedAt))/1000));document.getElementById('map-selection').innerHTML=`<div class="eyebrow">AIS OBSERVATION · ${e(p.source||'AISStream')}</div><h2>${e(p.name)}</h2><div class="status-row"><span>MMSI</span><strong>${e(p.mmsi)}</strong></div><div class="status-row"><span>Reported coordinates</span><span>${p.lat.toFixed(4)}, ${p.lon.toFixed(4)}</span></div><div class="status-row"><span>Speed / course</span><span>${p.speedKnots===null?'Unavailable':p.speedKnots+' kn'} / ${p.courseDegrees===null?'Unavailable':p.courseDegrees+'°'}</span></div><div class="status-row"><span>Received UTC</span><span>${e(p.receivedAt)}</span></div><div class="status-row"><span>Reception age</span><span>${age}s${age>180?' · Stale':''}</span></div><p class="source">Provider timestamp: ${e(p.providerTimestamp||'Not supplied')}. AIS reception does not verify a current vessel position.</p>`}
document.addEventListener('click',ev=>{const a=ev.target.closest('[data-ais-action]')?.dataset.aisAction;if(a==='start')startAIS();if(a==='stop')stopAIS();const p=ev.target.closest('[data-ais]');if(p)chooseAIS(p.dataset.ais);if(ev.target.closest('[data-route="ais"]')){location.hash='map';startAIS()}});
document.addEventListener('keydown',ev=>{const p=ev.target.closest('[data-ais]');if(p&&['Enter',' '].includes(ev.key)){ev.preventDefault();chooseAIS(p.dataset.ais)}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(aisTimer);else if(aisState.enabled&&location.hash.includes('map'))fetchAIS()});
window.addEventListener('hashchange',()=>{if(!location.hash.includes('map'))clearTimeout(aisTimer);else if(aisState.enabled)fetchAIS()});
